sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
   gs.info('Script executed for WOrkplace incident reporting');

    var a = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
    a.addQuery('sys_id', current.parent);
    a.query();
    if (a.next()) {
        if (current.state == 3 && current.short_description == 'Manager/Supervisor Investigation')
            a.state = 30;
        else if (current.state == 3 && current.short_description == 'Committee Review')
            a.state = 102;
		//	Advisor Investigation
		else if (current.state == 3 && current.short_description == 'Advisor Review')
            a.state = 105;
		else if (current.state == 4 && current.short_description == 'Advisor Review')
            a.state = 101;
		else if (current.state == 4 && current.short_description == 'Send the document to ESDC')
            a.state = 105;

        a.update();

    }
})(current, previous);
